		String[] names = { "b", "missing", "a" };
		var scratch = new ArrayList<Value>();
		var source = new QueryBindingSet();
		source.addBinding("a", vf.createIRI("urn:a"));
		source.addBinding("b", vf.createIRI("urn:b"));
		source.addBinding("extra", vf.createIRI("urn:ignored"));
		var output = new ByteArrayOutputStream();
		var builder = builder(output, true);
		builder.start(names);
		add(builder, names, scratch, source);
		source.setBinding("a", vf.createIRI("urn:changed"));
